sealed class Glyph {                              // immutable intrinsic state
    public readonly string Name; public readonly int W, H;
    Glyph(string n, int w, int h) { Name = n; W = w; H = h; }
    static readonly ConcurrentDictionary<string, Glyph> Pool = new();
    public static Glyph Get(string n, int w, int h) =>
        Pool.GetOrAdd(n, key => new Glyph(key, w, h));
}
// context: record Cell(Glyph Glyph, int X, int Y);
